description:
Driver Verifier's deadlock detection records the **order** in which locks are taken and reports a possible deadlock as soon as two code paths take the same locks in opposite orders, even if they have not actually deadlocked yet. Write it:

```cpp
class LockOrder
{
public:
    std::string acquire(int thread, const std::string& lock);   // "" or a problem
    std::string release(int thread, const std::string& lock);
};
```

- Each thread has its own stack of held locks.
- `acquire` while holding other locks records an order "A before B" from **every** held lock A to the new lock B. Before recording, if B can already reach A through recorded orders (B before ... before A), return `"possible deadlock: B -> ... -> A -> B"`: the existing chain from B to A (the shortest, choosing names alphabetically when several are as short), followed by the new lock again. The lock is still acquired.
- Acquiring a lock the thread already holds returns `"recursive acquire: <lock>"` and does not acquire it again.
- `release` of a lock the thread does not hold returns `"release of unheld lock: <lock>"`. Releasing a lock that is held but not the most recent is allowed (it is removed from wherever it is).

starter.solution.cpp:
#include <string>

class LockOrder
{
public:
    std::string acquire(int thread, const std::string& lock) { return ""; }
    std::string release(int thread, const std::string& lock) { return ""; }
};

solution.solution.cpp:
#include <algorithm>
#include <map>
#include <queue>
#include <set>
#include <string>
#include <vector>

class LockOrder
{
public:
    std::string acquire(int thread, const std::string& lock)
    {
        auto& held{ m_held[thread] };
        if (std::find(held.begin(), held.end(), lock) != held.end()) return "recursive acquire: " + lock;
        std::string problem;
        for (const std::string& a : held)
        {
            if (problem.empty())
            {
                const std::vector<std::string> path{ shortestPath(lock, a) };
                if (!path.empty())
                {
                    problem = "possible deadlock: ";
                    for (const auto& p : path) problem += p + " -> ";
                    problem += lock;
                }
            }
            m_before[a].insert(lock);
        }
        held.push_back(lock);
        return problem;
    }

    std::string release(int thread, const std::string& lock)
    {
        auto& held{ m_held[thread] };
        const auto it{ std::find(held.begin(), held.end(), lock) };
        if (it == held.end()) return "release of unheld lock: " + lock;
        held.erase(it);
        return "";
    }

private:
    std::vector<std::string> shortestPath(const std::string& from, const std::string& to) const
    {
        std::map<std::string, std::string> came{ { from, "" } };
        std::queue<std::string> q;
        q.push(from);
        while (!q.empty())
        {
            const std::string cur{ q.front() };
            q.pop();
            if (cur == to)
            {
                std::vector<std::string> path;
                for (std::string s{ to }; !s.empty(); s = came[s]) path.push_back(s);
                std::reverse(path.begin(), path.end());
                return path;
            }
            const auto it{ m_before.find(cur) };
            if (it == m_before.end()) continue;
            for (const std::string& next : it->second)          // std::set: alphabetical
                if (!came.count(next)) { came[next] = cur; q.push(next); }
        }
        return {};
    }

    std::map<int, std::vector<std::string>> m_held;
    std::map<std::string, std::set<std::string>> m_before;
};

unitTests:
TEST("a consistent order is fine") {
    LockOrder o; CHECK_EQ(o.acquire(1, "A"), std::string("")); CHECK_EQ(o.acquire(1, "B"), std::string("")); o.release(1, "B"); o.release(1, "A");
    CHECK_EQ(o.acquire(2, "A"), std::string("")); CHECK_EQ(o.acquire(2, "B"), std::string(""));
}
TEST("opposite orders") {
    LockOrder o; o.acquire(1, "A"); o.acquire(1, "B"); o.release(1, "B"); o.release(1, "A");
    o.acquire(2, "B"); CHECK_EQ(o.acquire(2, "A"), std::string("possible deadlock: A -> B -> A"));
}
TEST("longer cycles") {
    LockOrder o;
    o.acquire(1, "A"); o.acquire(1, "B"); o.release(1, "B"); o.release(1, "A");
    o.acquire(1, "B"); o.acquire(1, "C"); o.release(1, "C"); o.release(1, "B");
    o.acquire(2, "C"); CHECK_EQ(o.acquire(2, "A"), std::string("possible deadlock: A -> B -> C -> A"));
}
TEST("misuse") {
    LockOrder o; o.acquire(1, "A"); CHECK_EQ(o.acquire(1, "A"), std::string("recursive acquire: A")); CHECK_EQ(o.release(1, "Z"), std::string("release of unheld lock: Z"));
    CHECK_EQ(o.release(2, "A"), std::string("release of unheld lock: A")); o.acquire(1, "B"); CHECK_EQ(o.release(1, "A"), std::string("")); CHECK_EQ(o.release(1, "B"), std::string(""));
}

